public struct AppShellEnvironmentSpan: Sendable {
    private var state: LogSpanState
    private let emit: @Sendable (any LogEvent) -> Void
    private let `shell`: String
    private let `source`: String

    private init(`shell`: String, `source`: String, operationID: String, clock: LogSpanClock, emit: @escaping @Sendable (any LogEvent) -> Void) {
        state = LogSpanState(operationID: operationID, clock: clock)
        self.emit = emit
        self.`shell` = `shell`
        self.`source` = `source`
    }

    public static func begin(`shell`: String, `source`: String, operationID: String = UUID().uuidString.lowercased(), clock: LogSpanClock = .continuous, emit: @escaping @Sendable (any LogEvent) -> Void) -> Self {
        let span = Self(shell: `shell`, source: `source`, operationID: operationID, clock: clock, emit: emit)
        // Started is a DEBUG event; the sink drops it unless verbose diagnostics are on.
        emit(AppShellEnvironmentStarted(shell: `shell`, source: `source`, operationID: operationID))
        return span
    }

    public mutating func finish(`variables`: (Int64)? = nil) {
        guard let duration = state.end() else { return }
        emit(AppShellEnvironmentFinished(duration: `duration`, shell: `shell`, source: `source`, variables: `variables`, operationID: state.operationID))
    }

    public mutating func fail(_ error: any Error, `variables`: (Int64)? = nil) {
        guard let duration = state.end() else { return }
        emit(AppShellEnvironmentFailed(duration: `duration`, error: `error`, shell: `shell`, source: `source`, variables: `variables`, operationID: state.operationID))
    }
}

